var SERIAL_ENDPOINT="https://script.google.com/macros/s/AKfycbzxbj0xjFmjzDA6L5MNG4IqZKuiI0mb9SAOOXhJY_UeQmeTWE7ldaas1fFC6xqUzHn0/exec";var BASE_PDF_PATH="./assets/OFF-THE-RECORD.pdf";var SERIAL_TIMEOUT=15e3;async function stampAndDownload(buttonElement){var btn=buttonElement||document.getElementById("pdfDownloadBtn")||document.querySelector('[data-action="download-pdf"]');var originalText=btn?btn.textContent:"";if(btn){btn.textContent="PREPARING YOUR COPY...";btn.disabled=true}try{var serial=await getSerialNumber();console.log("[PDF Stamper] Serial assigned:",serial);var pdfBytes=await loadBasePdf();if(!pdfBytes){throw new Error("Failed to load base PDF")}var pdfDoc=await PDFLib.PDFDocument.load(pdfBytes);await applyLibrarySeal(pdfDoc,serial);applyMetadata(pdfDoc,serial);var stampedBytes=await pdfDoc.save();triggerDownload(stampedBytes,serial);fireAnalyticsEvent(serial)}catch(error){console.error("[PDF Stamper] Error:",error)}finally{if(btn){btn.textContent=originalText;btn.disabled=false}}return false}async function getSerialNumber(){if(SERIAL_ENDPOINT.indexOf("__APPS_SCRIPT_URL__")!==-1){console.warn("[PDF Stamper] Serial endpoint not configured, using fallback");return generateFallbackSerial()}try{var controller=new AbortController;var timeoutId=setTimeout(function(){controller.abort()},SERIAL_TIMEOUT);var readerName=localStorage.getItem("otr_reader_name")||"anonymous";var serialUrl=SERIAL_ENDPOINT+"?action=assign_serial&reader_name="+encodeURIComponent(readerName);var response=await fetch(serialUrl,{method:"GET",redirect:"follow",signal:controller.signal});clearTimeout(timeoutId);if(!response.ok){throw new Error("Serial endpoint returned "+response.status)}var data=await response.json();if(data&&data.serial){return data.serial}else{throw new Error("Invalid response from serial endpoint")}}catch(error){console.error("[PDF Stamper] Serial fetch failed:",error.message);return generateFallbackSerial()}}function generateFallbackSerial(){return"000-OFFLINE-10"}async function loadBasePdf(){try{var response=await fetch(BASE_PDF_PATH);if(!response.ok){throw new Error("PDF fetch failed: "+response.status)}return await response.arrayBuffer()}catch(error){console.error("[PDF Stamper] Failed to load PDF:",error);return null}}async function applyLibrarySeal(pdfDoc,serial){var pages=pdfDoc.getPages();var targetPage=pages.length>1?pages[1]:pages[0];var pageSize=targetPage.getSize();var fontBold=await pdfDoc.embedFont(PDFLib.StandardFonts.TimesRomanBold);var fontRegular=await pdfDoc.embedFont(PDFLib.StandardFonts.TimesRoman);var darkRed=PDFLib.rgb(139/255,0,0);var dateStr=formatDateWithTimezone();var line1Text="# "+serial;var line1Size=14;var line1Width=fontBold.widthOfTextAtSize(line1Text,line1Size);var line1Height=line1Size;var line2Text=dateStr;var line2Size=10;var line2Width=fontRegular.widthOfTextAtSize(line2Text,line2Size);var line2Height=line2Size;var paddingH=25;var paddingV=15;var lineSpacing=8;var contentWidth=Math.max(line1Width,line2Width);var contentHeight=line1Height+lineSpacing+line2Height;var boxWidth=contentWidth+paddingH*2;var boxHeight=contentHeight+paddingV*2;var margin=50;var boxX=pageSize.width-boxWidth-margin;var boxY=margin;targetPage.drawRectangle({x:boxX,y:boxY,width:boxWidth,height:boxHeight,borderColor:darkRed,borderWidth:2,borderOpacity:.85,opacity:0});var line1X=boxX+(boxWidth-line1Width)/2;var line1Y=boxY+paddingV+line2Height+lineSpacing;var line2X=boxX+(boxWidth-line2Width)/2;var line2Y=boxY+paddingV;targetPage.drawText(line1Text,{x:line1X,y:line1Y,size:line1Size,font:fontBold,color:darkRed,opacity:.85});targetPage.drawText(line2Text,{x:line2X,y:line2Y,size:line2Size,font:fontRegular,color:darkRed,opacity:.85})}function formatDateWithTimezone(){var now=new Date;var tz="UTC";try{var parts=new Intl.DateTimeFormat("en-US",{timeZoneName:"short"}).formatToParts(now);var tzPart=parts.find(function(p){return p.type==="timeZoneName"});if(tzPart){tz=tzPart.value}}catch(e){console.log("[PDF Stamper] Could not get timezone, using UTC")}var month=now.getMonth()+1;var day=now.getDate();var year=String(now.getFullYear()).slice(-2);var hours=now.getHours();var minutes=now.getMinutes();var ampm=hours>=12?"PM":"AM";hours=hours%12;if(hours===0)hours=12;var minuteStr=minutes<10?"0"+minutes:String(minutes);return month+"-"+day+"-"+year+" "+hours+":"+minuteStr+" "+ampm+" "+tz}function applyMetadata(pdfDoc,serial){pdfDoc.setTitle("OFF-THE-RECORD by Anthony Fenech");pdfDoc.setAuthor("Anthony Fenech");pdfDoc.setSubject("Digital Edition — # "+serial);pdfDoc.setKeywords([serial,"anthonyfenech.com","verified"]);pdfDoc.setCreator("OFF-THE-RECORD Digital Press");pdfDoc.setProducer("OFF-THE-RECORD Digital Press")}function triggerDownload(pdfBytes,serial){var blob=new Blob([pdfBytes],{type:"application/pdf"});var url=URL.createObjectURL(blob);var link=document.createElement("a");link.href=url;link.download=serial?"OFF-THE-RECORD-"+serial+".pdf":"OFF-THE-RECORD.pdf";document.body.appendChild(link);link.click();document.body.removeChild(link);setTimeout(function(){URL.revokeObjectURL(url)},1e3)}function fireAnalyticsEvent(serial){var payload={event:"pdf_download",serial:serial,reader_name:localStorage.getItem("otr_reader_name")||"anonymous",timestamp:(new Date).toISOString(),device:navigator.userAgent};try{if(typeof OTR_ANALYTICS_CONFIG!=="undefined"&&OTR_ANALYTICS_CONFIG.trackingEnabled){fetch(OTR_ANALYTICS_CONFIG.analyticsScriptUrl,{method:"POST",mode:"no-cors",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}).then(function(){console.log("[PDF Stamper] Analytics event fired:",serial)}).catch(function(err){console.log("[PDF Stamper] Analytics failed:",err.message)})}else{console.log("[PDF Stamper] Analytics (suppressed):",payload)}}catch(e){console.log("[PDF Stamper] Analytics error:",e.message)}}